/**
 * REST response normalizers — pure mapping functions.
 *
 * Data flow: fetch raw → normalize() → zod.parse(normalized) → return public DTO
 *
 * Backend field aliases (question vs question_text, answers vs options)
 * resolve here, before validation touches them.
 */

import type {
  RawSessionResponse,
  RawQuestionsResponse,
  RawFeedbackResponse,
} from './types.js';
import type { DiscoveryQuestion } from '../../types.js';

// ── Session ─────────────────────────────────────────────────────

export interface NormalizedSessionResponse {
  sessionId: string;
  welcomeText?: string;
  seedQuestions?: string[];
  aiDisabled?: boolean;
  disabledReason?: string | null;
}

export function normalizeSessionResponse(raw: RawSessionResponse): NormalizedSessionResponse {
  return {
    sessionId: raw.session_id ?? '',
    welcomeText: raw.welcome_text,
    seedQuestions: raw.seed_questions,
    aiDisabled: raw.ai_disabled,
    disabledReason: raw.disabled_reason,
  };
}

// ── Questions ───────────────────────────────────────────────────

/**
 * A choice's product count as a finite number, or null when it carries none.
 *
 * Numeric strings are accepted: backends and ORMs serialize counts as strings
 * routinely, and a `typeof === 'number'` test alone fails open — every choice
 * silently loses its count, the "Popular" heading disappears, and the symptom
 * is indistinguishable from a backend that never sent counts at all.
 */
function numericCount(raw: number | string | null | undefined): number | null {
  if (typeof raw === 'number') return Number.isFinite(raw) ? raw : null;
  if (typeof raw === 'string' && raw.trim() !== '') {
    const parsed = Number(raw);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

export function normalizeQuestions(raw: RawQuestionsResponse): DiscoveryQuestion[] {
  if (!raw.questions || !Array.isArray(raw.questions)) {
    return [];
  }

  // Sort by sort_order (if present) before mapping — preserves backend ordering
  const sorted = [...raw.questions].sort(
    (a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0),
  );

  return sorted.map((q) => {
    const rawAnswers = (q.answers || q.options || []).map((a) => ({
      id: String(a.id),
      text: a.text || a.answer_text || a.answer || '',
    }));
    const renderHint = q.answer_render_hint ?? undefined;
    // Coerce choice ids to string — modern backends ship "attrvalue_*" strings,
    // older ones sent numbers.
    const choices = q.answer_choices
      ? q.answer_choices.map((c) => {
          // `product_count` drives the "Popular" quick picks. Only carry it
          // when it resolves to a finite number: an undefined key is the
          // renderer's signal that no popularity ordering exists.
          const base = { id: String(c.id), value: c.value };
          const count = numericCount(c.product_count);
          return count === null ? base : { ...base, productCount: count };
        })
      : undefined;

    // For "choice" questions the renderer iterates `answers`, but backends
    // increasingly ship the options in `answer_choices` and leave `answers`
    // empty. Mirror the choices into `answers` so the pill list still renders.
    // `?? 'choice'` because the hint is optional on the wire and documented as
    // defaulting to `choice`. Matching only the literal left a question with
    // no hint and no `answers` rendering an empty radiogroup — the wizard
    // showed the question text over nothing and could not be advanced.
    const answers =
      rawAnswers.length === 0 &&
      (renderHint ?? 'choice') === 'choice' &&
      choices &&
      choices.length > 0
        ? choices.map((c) => ({ id: c.id, text: c.value }))
        : rawAnswers;

    return {
      id: String(q.question_id ?? q.id),
      question: q.question || q.question_text || '',
      answers,
      allowOther: q.allow_other,
      productTypeId: q.product_type_id,
      answerRenderHint: renderHint,
      answerChoices: choices,
    };
  });
}

// ── Feedback ────────────────────────────────────────────────────

export interface NormalizedFeedbackResponse {
  success: boolean;
  feedbackId: string;
  message?: string;
}

export function normalizeFeedbackResponse(raw: RawFeedbackResponse): NormalizedFeedbackResponse {
  return {
    success: raw.success ?? false,
    feedbackId: raw.feedbackId ?? raw.feedback_id ?? '',
    message: raw.message,
  };
}
