/**
 * DataLayer bridge — forwards a storefront's own analytics arrays into
 * EventService.
 *
 * "The dataLayer" is not one array, and assuming it is loses every eCommerce
 * event on some stores:
 *
 * - `window.dataLayer` is GTM's transport. It carries `gtm.js` / `gtm.dom` /
 *   `gtm.load` plus whatever tags push, so `gtm.`-prefixed names are filtered
 *   out and anything else is forwarded.
 * - `window.ElevarDataLayer` is Elevar's own array. Elevar owns its event
 *   schema and enriches before GTM sees anything, so on an Elevar store every
 *   eCommerce signal (`dl_view_item`, `dl_add_to_cart`, `dl_begin_checkout`,
 *   `dl_purchase`, …) lands HERE and never in `window.dataLayer`. Measured on
 *   a production Elevar storefront across a PLP and a PDP: the GTM array held
 *   nothing but lifecycle events, while the Elevar array held the full payload.
 *
 * Event names are forwarded VERBATIM. The backend owns spelling
 * (`event_name_normalizer.canonical_event_name`), so a new storefront
 * vocabulary is a config row there rather than a mapping table here that can
 * drift out of sync with it.
 *
 * Both arrays are read by polling, never by wrapping `push` — Elevar replaces
 * `push` with its own implementation, so patching it fights the vendor for
 * ownership of a function we do not own. Each poll forwards the entries it has
 * not already forwarded, tracked by object identity rather than by a count
 * (see `forwarded`).
 *
 * ── Why the progress state is module-level ──────────────────────────
 *
 * A page mounts SEVERAL OmniguideProviders: `auto-init` hands one shared
 * config to BCSearchIntegration, BCProductFitIntegration and
 * BCCategoryGuideIntegration, each rendering its own React root. Each one runs
 * the effect that starts this bridge, and each unmounts independently (a
 * category container swap remounts one of them mid-session).
 *
 * So `forwarded` and `pageViewSent` CANNOT live in a start call's closure: a
 * stop→start cycle would forget them and re-forward the entire array plus a
 * second `page_view`. They live at module scope, where a detach cannot reach
 * them, and the poller itself is refcounted so the last detach — not the
 * first — stops it.
 */

import { createScopedLogger } from '../logger.js';
import { sanitizeUrl } from '../safe-url.js';
import { getEventService } from '../event-registry.js';

const log = createScopedLogger('DataLayerBridge');

const POLL_INTERVAL_MS = 1000;

export interface DataLayerBridgeConfig {
  /** Watch `window.ElevarDataLayer`. */
  elevar?: boolean;
  /** Watch `window.dataLayer`, skipping GTM's own lifecycle events. */
  gtm?: boolean;
  /** Emit exactly one `page_view` per document load. */
  pageView?: boolean;
}

interface SourceSpec {
  /** Global holding the array. */
  key: string;
  /** Names this source must not forward. */
  skip?: (eventName: string) => boolean;
}

const SOURCES: Record<'elevar' | 'gtm', SourceSpec> = {
  elevar: { key: 'ElevarDataLayer' },
  // The filter is the GTM source's, not the bridge's: an Elevar store that
  // ever names an event `gtm.something` must still be forwarded.
  gtm: { key: 'dataLayer', skip: name => name.startsWith('gtm.') },
};

/**
 * Which entries have already been handed to EventService.
 *
 * Progress is tracked by entry IDENTITY, not by a count. A length index is the
 * wrong signal for an array we do not own: a vendor can clear it in place and
 * refill it to the same length (an index forwards the refill's first entries
 * and loses the rest, permanently), swap in a copy (an index re-forwards
 * everything, double-counting a `dl_purchase`), push a superset copy, or
 * `splice` out an entry (shifting every later one under the index). No pair of
 * length/array-identity guards handles all of those — the equal-length and
 * superset cases pull in opposite directions.
 *
 * Forwarding each OBJECT once collapses all of them into one rule, and needs
 * no reconciliation: a refilled array holds new objects, so they are forwarded;
 * a copied or spliced array holds the same objects, so they are not.
 *
 * ponytail: rescans the whole array each tick rather than remembering a
 * position. These arrays hold tens of entries, not thousands. If one ever grows
 * past a few hundred, keep a hint index for the common append-only case and
 * fall back to the full scan when identity says the array changed.
 *
 * A WeakSet, so a cleared array's entries are collectable — this outlives every
 * detach and must not pin a page's worth of vendor payloads.
 */
let forwarded = new WeakSet<object>();

/**
 * Most entries forwarded in one tick.
 *
 * The bridge holds everything until an EventService registers and then replays
 * it in one synchronous pass. EventService's queue trims OLDEST-first at 200,
 * so an unpaced replay of a large backlog evicts the very entries the hold
 * existed to preserve, plus any genuine SDK events already queued. Realistic
 * backlogs are 5-30, so this is tail cover; the remainder simply goes next tick.
 */
const MAX_FORWARDS_PER_TICK = 50;

// ── Module-level progress. A detach must never reset these. ────────
let pageViewSent = false;

// ── Module-level poller, refcounted across providers. ──────────────
let refCount = 0;
let intervalId: number | null = null;
let hiddenListener: (() => void) | null = null;
let activeConfig: DataLayerBridgeConfig | null = null;

interface ParsedEntry {
  name: string;
  payload: Record<string, unknown>;
}

/**
 * Parse one array entry into a name and payload, or null if it is not an event.
 *
 * Two shapes reach these arrays, and they must be read as a unit — deciding
 * the name from one shape and the payload from the other mixes them:
 *
 * - a plain object carrying `event` (GTM's convention, and Elevar's);
 * - the `arguments` object gtag pushes for `gtag('event', '<name>', {...})`,
 *   which is array-LIKE but not an Array and carries its parts under
 *   "0" / "1" / "2". gtag's non-event commands (`set`, `config`, `consent`,
 *   `js`) land in the same array and are skipped.
 */
/**
 * Keys EventService puts on the envelope itself.
 *
 * `track()` builds `{ event, timestamp, ...data }` — the caller's data spreads
 * LAST, so any of these surviving in a vendor payload silently overwrites the
 * envelope. A gtag params object carrying `event` renames the event on the
 * wire (`add_to_cart` arriving as whatever the vendor wrote); a `timestamp`
 * replaces the SDK's ISO time with a value of unknown format; a `message_id`
 * attributes a storefront event to an Omniguide conversation that never
 * produced it.
 *
 * Dropped rather than renamed: preserving them under a namespaced key would be
 * inventing vocabulary the backend does not know. If any of this turns out to
 * be worth keeping, it should be a deliberate field, not a collision.
 */
const ENVELOPE_KEYS = ['event', 'timestamp', 'message_id'] as const;

/**
 * Marker the SDK stamps on every event it hands its own analytics adapter.
 *
 * `useAnalyticsTracking` delivers each SDK event TWICE by design: once to
 * EventService (backend) and once to the theme's `analyticsAdapter`, whose
 * documented implementation pushes to `window.dataLayer`. With `gtm: true`
 * this bridge reads that array, so without a skip the SDK's own events return
 * through the front door and are counted a second time.
 *
 * A marker rather than a name list: the theme interceptor this replaces
 * skipped by prefix (`ai_search_*`, `AI Search -`, `scroll_for_more`) and that
 * list has already drifted past `rec_product_clicked`, `product_rec_*` and
 * `category_rec_*`. A key travels with the event and cannot fall behind the
 * vocabulary.
 *
 * Limit: it only works for an adapter that spreads the properties it is given
 * onto the pushed object, as the documented one does. An adapter that rebuilds
 * the payload drops the marker and its events round-trip again.
 */
export const SDK_ORIGIN_MARKER = 'omniguide_sdk';

/**
 * Events and payload keys carrying shopper identity, dropped before anything
 * reaches EventService.
 *
 * `track()` persists to `localStorage['omniguide_event_queue']` for 24h BEFORE
 * consent is read, so anything forwarded here is at rest on the shopper's
 * device regardless of what they later deny. `ARCHITECTURE.md` and
 * `SECURITY.md` both publish that no personal information is cached client
 * side, and forwarding Elevar's `dl_user_data` verbatim would make that false.
 *
 * A blocklist, not an allowlist: the whole point of the bridge is that the
 * backend owns the vocabulary, so an allowlist would silently drop each new
 * eCommerce field until someone noticed. This list can only ever err toward
 * forwarding too little of what we already know is identity.
 */
const BLOCKED_EVENTS = new Set(['dl_user_data']);
// `user_data` is the GA4 / Google Ads enhanced-conversions envelope — the
// standard identity carrier in `window.dataLayer`, which is exactly what the
// `gtm` source reads. It holds `email_address`, `phone_number` and an
// `address` block. It was missing here, so the source most likely to carry
// identity was the one source not covered.
const BLOCKED_KEYS = ['user_properties', 'customer', 'user_data'] as const;

// SDK_ORIGIN_MARKER joins these: an entry that reaches the backend carrying it
// would be shipping an internal routing flag as a storefront field.
const DROPPED_KEYS: readonly string[] = [...ENVELOPE_KEYS, ...BLOCKED_KEYS, SDK_ORIGIN_MARKER];

/**
 * Remove the dropped keys at EVERY depth, not just the top level.
 *
 * A one-level strip was the whole protection, and a vendor only has to nest to
 * defeat it: `ecommerce.customer.email` and an `actionField` carrying
 * `user_properties` both reached the queue verbatim while the top-level keys
 * of the same names were being removed. Identity does not reliably sit at the
 * root of these payloads — Elevar's checkout events in particular carry it
 * under `ecommerce`.
 *
 * Rebuilds containers rather than mutating, because this runs on the vendor's
 * live object.
 *
 * `ancestors` tracks the path currently being walked, not every object seen. A
 * WeakSet of everything visited looks like the same thing and is not: a payload
 * that legitimately references one object twice (the same product under two
 * keys) would have the second reference dropped as though it were a cycle.
 * Entries are removed on the way back out, so only a true self-reference —
 * which would otherwise hang the poll on the vendor's own array — resolves to
 * `undefined`.
 *
 * Class instances ARE walked. Passing them through because they are not plain
 * objects fails open: identity inside one would reach the wire untouched, and
 * these payloads are bound for `JSON.stringify` anyway, so rebuilding them as
 * plain objects costs nothing downstream. Only the built-ins whose meaning
 * lives outside their enumerable properties are passed through — a Date
 * rebuilt as `{}` would lose the date.
 */
function stripDroppedKeys(
  payload: Record<string, unknown>,
  ancestors: Set<object> = new Set(),
): Record<string, unknown> {
  return stripValue(payload, ancestors) as Record<string, unknown>;
}

const OPAQUE = [Date, RegExp, Map, Set, WeakMap, WeakSet] as const;

function stripValue(value: unknown, ancestors: Set<object>): unknown {
  if (!value || typeof value !== 'object') return value;
  if (OPAQUE.some(ctor => value instanceof ctor)) return value;
  if (ancestors.has(value)) return undefined;

  ancestors.add(value);
  try {
    if (Array.isArray(value)) return value.map(item => stripValue(item, ancestors));

    const out: Record<string, unknown> = {};
    for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
      if (DROPPED_KEYS.includes(key)) continue;
      out[key] = stripValue(child, ancestors);
    }
    return out;
  } finally {
    ancestors.delete(value);
  }
}

function parseEntry(entry: unknown): ParsedEntry | null {
  if (!entry || typeof entry !== 'object') return null;
  const e = entry as Record<string, unknown>;

  // Each branch takes BOTH name and payload from the shape it matched —
  // reading the name off one and the payload off the other would mix them on
  // a hybrid entry. An empty `event` names nothing, so it falls through to the
  // gtag check rather than claiming the entry.
  // Both rejections sit here rather than in the drain loop so they apply to
  // every source and every entry shape, and so a blocked entry is still MARKED
  // as seen — a skipped entry must not be reconsidered on the next tick.
  if (e[SDK_ORIGIN_MARKER]) return null;

  if (typeof e['event'] === 'string' && e['event']) {
    if (BLOCKED_EVENTS.has(e['event'])) return null;
    return { name: e['event'], payload: stripDroppedKeys(e) };
  }

  if (e['0'] === 'event' && typeof e['1'] === 'string' && e['1']) {
    if (BLOCKED_EVENTS.has(e['1'])) return null;
    const params = e['2'];
    // The marker check above only sees the ENTRY. An adapter written as
    // `gtag('event', name, {...properties})` spreads the properties it is
    // given — which the documented limit says is the safe shape — but they
    // land under `2`, so the marker rides there and the entry itself is bare.
    // Without this the SDK's own events round-trip on that adapter.
    if (params && typeof params === 'object'
        && (params as Record<string, unknown>)[SDK_ORIGIN_MARKER]) return null;
    return {
      name: e['1'],
      payload:
        params && typeof params === 'object'
          ? stripDroppedKeys(params as Record<string, unknown>)
          : {},
    };
  }

  return null;
}

/**
 * Hand EventService a copy, not the vendor's own object.
 *
 * The queue holds the object and serializes it at flush, up to 5s later.
 * Elevar reuses and mutates its `ecommerce` objects between pushes, so a
 * shared reference lets a later mutation rewrite an event already counted as
 * sent. Falls back to the original when the payload is not cloneable — worse
 * than a copy, still better than dropping the event.
 */
function detachPayload(payload: Record<string, unknown>): Record<string, unknown> {
  try {
    return structuredClone(payload);
  } catch (error) {
    // Logged, not silent: the fallback hands EventService the vendor's live
    // object, which is precisely the case this function exists to prevent. A
    // payload carrying a function (GTM's `eventCallback` is enough) or a DOM
    // node lands here, and without a line in the console a store where the
    // protection never engages looks identical to one where it does.
    log.warn('structuredClone failed; forwarding the vendor object by reference:', error);
    return payload;
  }
}

function readArray(key: string): unknown[] {
  const value = (window as unknown as Record<string, unknown>)[key];
  return Array.isArray(value) ? value : [];
}

function activeSources(): SourceSpec[] {
  const specs: SourceSpec[] = [];
  if (activeConfig?.elevar) specs.push(SOURCES.elevar);
  if (activeConfig?.gtm) specs.push(SOURCES.gtm);
  return specs;
}

type RegisteredEventService = NonNullable<ReturnType<typeof getEventService>>;

/**
 * Emit the document's single page_view, once delivery is possible.
 *
 * Contained, for the same reason the entry loop is: a `track` that throws here
 * used to abort drain() before a single source was read, and because
 * pageViewSent stays false it threw again every tick — one bad page_view
 * wedged every source for the life of the page. Measured: 11 page_view
 * attempts, zero entries forwarded.
 */
function emitPageViewOnce(service: RegisteredEventService): void {
  if (!activeConfig?.pageView || pageViewSent) return;
  try {
    service.track('page_view', {
      // Sanitised like every other analytics URL in the SDK: a shopper can
      // land on a path carrying a reset token or a session id in the query,
      // and page_location would otherwise ship it verbatim.
      page_location: sanitizeUrl(window.location.href),
      page_path: window.location.pathname,
      page_title: document.title,
    });
    // After the call, not before: a throwing track should be retried next tick
    // rather than silently consuming the page's only page_view.
    pageViewSent = true;
  } catch (error) {
    log.error('page_view could not be forwarded; continuing with sources:', error);
  }
}

/**
 * Forward one source's unseen entries, returning the budget left over.
 *
 * An entry is marked forwarded BEFORE the track call, not after: an entry that
 * throws has still been attempted, and retrying it every tick would wedge this
 * source — and every source after it — for the life of the page.
 */
function drainSource(
  spec: SourceSpec,
  service: RegisteredEventService,
  budget: number,
): number {
  let left = budget;
  for (const entry of readArray(spec.key)) {
    if (left <= 0) return 0;
    if (!entry || typeof entry !== 'object') continue;
    if (forwarded.has(entry)) continue;
    forwarded.add(entry);
    try {
      const parsed = parseEntry(entry);
      if (!parsed) continue;
      if (spec.skip?.(parsed.name)) continue;
      // Decremented BEFORE the call: a throwing entry still consumed an
      // attempt, and leaving it free let one tick blow past the cap entirely
      // (60 throwing entries ahead of 60 good ones made 110 calls against a
      // budget of 50) — the unpaced burst the cap exists to prevent, arriving
      // on exactly the day EventService is the thing misbehaving.
      left--;
      service.track(parsed.name, detachPayload(parsed.payload));
    } catch (error) {
      log.error(`Skipping unforwardable entry on ${spec.key}:`, error);
    }
  }
  return left;
}

/**
 * Forward everything not yet seen on each source.
 *
 * Nothing is marked until an EventService exists to hand events to.
 * `trackEvent` is a no-op while the registry is empty, so marking entries we
 * could not deliver would drop them with no queue and no retry. Holding them
 * instead makes the bridge's start time irrelevant: it replays the whole array
 * whenever delivery becomes possible.
 */
function drain(unbounded = false): void {
  const service = getEventService();
  if (!service) return;

  emitPageViewOnce(service);

  // The cap bounds a poll tick, where the remainder genuinely does go next
  // tick. On the way out there is no next tick, so the budget would not pace
  // the work — it would discard the tail with the page. Measured before this:
  // a 300-entry backlog at tab-hide forwarded 50 and lost 250.
  let budget = unbounded ? Number.POSITIVE_INFINITY : MAX_FORWARDS_PER_TICK;
  for (const spec of activeSources()) {
    budget = drainSource(spec, service, budget);
    if (budget <= 0) return;
  }
}

function tick(unbounded = false): void {
  try {
    drain(unbounded);
  } catch (error) {
    log.error('Drain failed:', error);
  }
}

function stopPolling(): void {
  if (intervalId !== null) window.clearInterval(intervalId);
  if (hiddenListener) document.removeEventListener('visibilitychange', hiddenListener);
  intervalId = null;
  hiddenListener = null;
  activeConfig = null;
}

/**
 * Start forwarding storefront dataLayer events. Returns a detach function.
 *
 * Safe to call once per mounted provider: the poller is refcounted, so the
 * LAST detach stops it rather than the first. Each caller's detach is its own
 * and is idempotent — one provider unmounting can neither stop another
 * provider's bridge nor orphan a live interval.
 *
 * Off by default and opt-in per flag, because a theme that already ships its
 * own dataLayer interceptor would otherwise deliver every event twice.
 */
export function startDataLayerBridge(config: DataLayerBridgeConfig): () => void {
  if (typeof window === 'undefined') return () => {};
  if (!config.elevar && !config.gtm && !config.pageView) return () => {};

  // First caller wins. Every provider on the page is handed the same config
  // object by auto-init, so there is nothing to merge.
  activeConfig ??= config;
  refCount++;

  if (intervalId === null) {
    // A tab going hidden is the last reliable moment to catch events pushed
    // since the previous tick. Anything forwarded there is already persisted
    // by EventService's queue, so it survives losing the race with unload.
    hiddenListener = () => {
      if (document.visibilityState === 'hidden') tick(true);
    };
    document.addEventListener('visibilitychange', hiddenListener);
    intervalId = window.setInterval(tick, POLL_INTERVAL_MS);
    tick();
  }

  let detached = false;
  return () => {
    if (detached) return;
    detached = true;
    refCount--;
    if (refCount <= 0) {
      refCount = 0;
      stopPolling();
    }
  };
}

/** @internal Stop the bridge and clear ALL module state (for testing only). */
export function _resetDataLayerBridge(): void {
  stopPolling();
  refCount = 0;
  forwarded = new WeakSet();
  pageViewSent = false;
}
